"""Fitting a theory under a link to any paradigm's responses (docs/auto_open/PLAN.md §3).

The closed campaign's fit (`src.rsa.fit`) knows one likelihood, a choice among objects. Here
the likelihood is the link's (`src.rsa_open.links.LinkLikelihood`): the theory gives each
trial's latent posterior over the objects of its scene, and the link scores the response. The
closed fit is left untouched, so the closed campaign's frozen results cannot move; under the
choice link the two give the same per-trial log-likelihood (tests/test_rsa_open_fit.py).

- `TheoryModel` loads a theory file (``PARAMS``, ``listener``, optionally ``speaker``) with the
  closed loader. Every theory has a speaker (PI 2026-10-21): its own, or the one derived from
  its listener (`TheoryModel.group_speaker`).
- `OpenData` checks every response against its scene and its link, and groups the trials by
  display shape.
- `fit` samples theory and link parameters jointly with NUTS (the closed fit's settings) and
  stores each trial's pointwise log-likelihood.
- `simulate` draws responses from a theory and link; `recovery_check` simulates from known
  parameters, refits and reports whether they come back: the test every link must pass,
  library and designer-proposed alike.
"""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path
from typing import Any, Dict, List, Mapping, Optional, Sequence, Tuple

import arviz as az
import jax
import jax.numpy as jnp
import numpy as np
import numpyro
from numpyro.infer import MCMC, NUTS

from src.models.pymc_inference import convergence_problems
from src.rsa.context import Context, ShapeGroup, group_by_shape
from src.rsa.fit import FitSettings, draw_batches
from src.rsa.model_file import ModelContractViolation, RSAModel
from src.rsa_open.links import LinkLikelihood
from src.rsa_open.port import LISTENER

OBSERVED_SITE = "response"


class TheoryModel(RSAModel):
    """A theory file, loaded like a model file but evaluated through ``listener``.

    Its speaker (``group_speaker``) is the file's own ``speaker(params, ctx)``, an
    (N_UTT, N_OBJ) array whose column r is P(message | target r), when it defines one; else the
    speaker derived from its listener:

        speaker(u | r) ∝ listener(r | u)   over the scene's real messages (never the sink),

    the speaker who expects this theory's listener. It has no parameter of its own: a speaker
    link's temperature is its rationality. When no real message is true of r for this listener
    (every listener(r | u) is 0), the speaker is indifferent: uniform over the real messages.
    """

    def _choice_probs(self, shape: Tuple[int, int]):
        fn = getattr(self.module(shape), LISTENER, None)
        if not callable(fn):
            raise ModelContractViolation(
                f"{self.path.name} must define {LISTENER}(params, ctx) returning the listener's "
                f"posterior over the objects, shape (N_OBJ,)")
        return fn

    @property
    def params(self) -> Dict[str, Any]:
        """The theory's priors. Unlike a model file's, they may be empty: a theory with no free
        parameters (the literal listener, once its lapse went to the link) is a fixed prediction."""
        from collections.abc import Mapping as _Mapping

        from numpyro.distributions import Distribution

        params = getattr(self._any_module(), "PARAMS", None)
        if not isinstance(params, _Mapping):
            raise ModelContractViolation(f"{self.path.name} must define PARAMS, a dict of parameter "
                                         f"name -> numpyro distribution (it may be empty)")
        bad = [k for k, v in params.items() if not isinstance(v, Distribution)]
        if bad:
            raise ModelContractViolation(f"PARAMS entries {bad} in {self.path.name} are not numpyro distributions")
        return dict(params)

    def latent_draws(self, params: Mapping[str, Any], group: ShapeGroup, speaker: bool, n_draws: int) -> jnp.ndarray:
        """(n_draws, trials, ...) listener posteriors or speakers at a batch of parameter draws; a
        theory without parameters gives the same prediction at every draw."""
        if not self.params:
            one = (self.group_speaker if speaker else self.group_probs)({}, group)
            return jnp.broadcast_to(one[None], (n_draws, *one.shape))
        return (self.draws_speaker if speaker else self.draws_probs)(params, group)

    def has_own_speaker(self) -> bool:
        return callable(getattr(self._any_module(), "speaker", None))

    def _speaker_fn(self, shape: Tuple[int, int]):
        own = getattr(self.module(shape), "speaker", None)
        if callable(own):
            return own
        listener = self._choice_probs(shape)

        def derived(params, ctx):
            heard = lambda u: listener(params, ctx._replace(utterance=u, is_prior=jnp.zeros_like(ctx.is_prior)))  # noqa: E731
            table = jax.vmap(heard)(jnp.arange(ctx.lex.shape[0], dtype=ctx.utterance.dtype))  # (N_UTT, N_OBJ)
            real = (1.0 - ctx.is_sink)[:, None]
            weights = table * real
            total = weights.sum(axis=0, keepdims=True)
            indifferent = jnp.broadcast_to(real / real.sum(), weights.shape)
            return jnp.where(total > 0, weights / jnp.where(total > 0, total, 1.0), indifferent)

        return derived

    def group_speaker(self, params: Mapping[str, Any], group: ShapeGroup) -> jnp.ndarray:
        """(trials, N_UTT, N_OBJ) speaker distributions for one shape group."""
        key = ("speaker", group.shape)
        if key not in self._jitted:
            fn = self._speaker_fn(group.shape)
            self._jitted[key] = jax.jit(lambda p, arrays: jax.vmap(lambda ctx: fn(p, ctx))(arrays))
        return self._jitted[key](dict(params), group.arrays)

    def draws_speaker(self, params: Mapping[str, Any], group: ShapeGroup) -> jnp.ndarray:
        """(draws, trials, N_UTT, N_OBJ) for a batch of parameter draws."""
        key = ("speaker draws", group.shape)
        if key not in self._jitted:
            fn = self._speaker_fn(group.shape)
            per_draw = lambda p, arrays: jax.vmap(lambda ctx: fn(p, ctx))(arrays)  # noqa: E731
            self._jitted[key] = jax.jit(jax.vmap(per_draw, in_axes=(0, None)))
        return self._jitted[key](dict(params), group.arrays)


def _latent(theory: TheoryModel, link: LinkLikelihood, params, group: ShapeGroup, draws: bool = False,
            n_draws: int = 0):
    if draws:
        return theory.latent_draws(params, group, link.side == "speaker", n_draws)
    return (theory.group_speaker if link.side == "speaker" else theory.group_probs)(params, group)


@dataclass(frozen=True)
class OpenData:
    """Trials grouped by display shape, each response checked and encoded for its link."""

    groups: List[ShapeGroup]
    encoded: List[Dict[str, jnp.ndarray]]  # per group, the link's response arrays
    n_trials: int

    @classmethod
    def build(cls, contexts: Sequence[Context], responses: Sequence[Mapping[str, Any]],
              link: LinkLikelihood) -> "OpenData":
        if len(contexts) != len(responses):
            raise ValueError(f"{len(contexts)} scenes but {len(responses)} responses")
        per_trial = [link.encode(ctx, r, i) for i, (ctx, r) in enumerate(zip(contexts, responses))]
        groups = list(group_by_shape(contexts).values())
        encoded = [link.stack([per_trial[i] for i in g.indices]) for g in groups]
        return cls(groups, encoded, len(contexts))


def _split(theory: RSAModel, link: LinkLikelihood, params: Mapping[str, Any]):
    theory_params = {k: params[k] for k in theory.params}
    link_params = {k: params[k] for k in link.params}
    return theory_params, link_params


def trial_log_lik(theory: RSAModel, link: LinkLikelihood, data: OpenData,
                  params: Mapping[str, Any]) -> jnp.ndarray:
    """(trials,) log-likelihood of each response at one parameter setting, in input order."""
    tp, lp = _split(theory, link, params)
    out = jnp.zeros(data.n_trials)
    for group, enc in zip(data.groups, data.encoded):
        ll = link.log_lik(_latent(theory, link, tp, group), lp, enc, group.arrays, jnp.asarray(group.classes))
        out = out.at[jnp.asarray(group.indices)].set(ll)
    return out


def _numpyro_model(theory: RSAModel, link: LinkLikelihood, data: OpenData):
    params = {name: numpyro.sample(name, prior) for name, prior in theory.params.items()}
    for name, prior in link.params.items():
        if name in params:
            raise ValueError(f"theory parameter {name!r} belongs to the {link.name!r} link")
        params[name] = numpyro.sample(name, prior)
    tp, lp = _split(theory, link, params)
    total = 0.0
    for group, enc in zip(data.groups, data.encoded):
        total = total + jnp.sum(link.log_lik(_latent(theory, link, tp, group), lp, enc, group.arrays,
                                             jnp.asarray(group.classes)))
    numpyro.factor(OBSERVED_SITE, total)


def pointwise_log_lik(theory: RSAModel, link: LinkLikelihood, data: OpenData,
                      flat: Mapping[str, np.ndarray]) -> np.ndarray:
    """(draws, trials) log-likelihood of each response at each posterior draw."""
    n_draws = len(next(iter(flat.values())))
    out = np.empty((n_draws, data.n_trials), dtype=np.float32)
    for group, enc in zip(data.groups, data.encoded):
        classes = jnp.asarray(group.classes)
        per_draw = jax.vmap(lambda latent, lp: link.log_lik(latent, lp, enc, group.arrays, classes))
        start = 0
        for n, params in draw_batches(flat, np.arange(n_draws)):
            tp, lp = _split(theory, link, params)
            batch = len(next(iter(params.values())))
            latent = _latent(theory, link, tp, group, True, batch)
            out[start:start + n, group.indices] = np.asarray(per_draw(latent, lp))[:n]
            start += n

"""Admission of a theorist's theory to the open loop (the closed loop's `src.rsa.loop.gates`, for
theories fitted to every paradigm of the chain).

A candidate directory holds ``candidate.py`` (a theory: ``PARAMS``, ``listener(params, ctx)``
and optionally ``speaker(params, ctx)``, `src.rsa_open.fit.TheoryModel`) and ``hypothesis.md``.
It is admitted only if, in order:

1. the code gate passes (`src.rsa.loop.code_gate`);
2. it is a theory, not a model of one paradigm: it defines ``listener`` and no
   ``choice_probs``, and none of its parameters is a link's (temperature, lapse and the
   links' own: the response process belongs to the paradigm, `src.rsa_open.links`);
3. it loads and meets the **listener contract** (`src.rsa.model_file.check_contract`) and the
   **speaker contract** (`check_speaker_contract`: every target's distribution over the
   scene's real messages, the sink never said, finite gradients) on every scene of the corpus
   and of the novelty pool;
4. its fit to the corpus (every block, `src.rsa_open.loop.fitting.loop_fit`) finishes within
   the time limit, gives no observed response probability zero and converges (after the one
   refit);
5. it is novel: its posterior-mean predictions on the novelty pool, listener and speaker
   both, are at least the threshold (RMSE) from every admitted theory's.

Every refusal carries a reason written for the agent that will repair it; infrastructure
failures raise.
"""

from __future__ import annotations

import ast
from dataclasses import dataclass
from pathlib import Path
from typing import Mapping, Optional, Sequence

import jax
import jax.numpy as jnp
import numpy as np

from src.rsa.context import Context, group_by_shape, unique_contexts
from src.rsa.fit import FitSettings, class_probs, draw_batches
from src.rsa.loop.code_gate import code_problems
from src.rsa.loop.fitting import ModelFailure, is_model_failure
from src.rsa.loop.gates import read_candidate
from src.rsa.loop.novelty import closest
from src.rsa.model_file import ModelContractViolation, check_contract, prior_draws
from src.rsa_open.corpus import Block, CorpusFit
from src.rsa_open.fit import TheoryModel
from src.rsa_open.loop.fitting import loop_fit

MAX_POOL_DRAWS = 100
SPEAKER_SUM_TOLERANCE = 1e-4


@dataclass
class Admission:
    admitted: bool
    reason: str
    fit: Optional[CorpusFit] = None
    pool_preds: Optional[np.ndarray] = None


@dataclass(frozen=True)
class GateConfig:
    corpus_path: Path
    cache_dir: Path
    settings: FitSettings
    novelty_threshold: float
    time_limit_sec: Optional[float]


def _refuse(reason: str, **kw) -> Admission:
    return Admission(False, reason, **kw)


def link_parameter_names() -> set:
    from src.rsa_open.links import LINKS, likelihood

    from src.rsa_open.links import SECOND_PREFIX

    names = {k for name in LINKS for k in likelihood(name, scale_points=5, total_points=100).params}
    return names | {SECOND_PREFIX + k for k in names}  # a two-measure paradigm's second link


def theory_shape_problems(source: str) -> list:
    """Why a file is not a paradigm-free theory (empty when it is one)."""
    tree = ast.parse(source)
    defined = {n.name for n in tree.body if isinstance(n, ast.FunctionDef)}
    problems = []
    if "listener" not in defined:
        problems.append("it defines no listener(params, ctx)")
    if "choice_probs" in defined:
        problems.append("it defines choice_probs: a theory gives the listener's posterior (listener) and, if "
                        "it likes, the speaker (speaker); the paradigm's link turns them into responses")
    return problems


def check_speaker_contract(theory: TheoryModel, groups, *, n_draws: int = 2, seed: int = 0) -> None:
    """Raise `ModelContractViolation` unless the theory's speaker (its own or the derived one) is,
    for every target, a distribution over the scene's real messages with finite gradients."""
    for draw in prior_draws(theory.params, n_draws, seed) if theory.params else [{}]:
        for shape, group in groups.items():
            n_obj, n_utt = shape
            where = f"{theory.path.name}'s speaker on {n_obj}-object scenes"
            s = np.asarray(theory.group_speaker(draw, group))
            if s.shape != (len(group.indices), n_utt, n_obj):
                raise ModelContractViolation(f"{where}: speaker must return shape (N_UTT, N_OBJ) = ({n_utt}, {n_obj}) "
                                             f"per trial; got {s.shape[1:]}")
            if not np.all(np.isfinite(s)) or s.min() < -1e-6:
                raise ModelContractViolation(f"{where}: probabilities are not all finite and non-negative")
            sink = np.asarray(group.arrays.is_sink) > 0
            if np.any(s[np.broadcast_to(sink[..., None], s.shape)] > 1e-6):
                raise ModelContractViolation(f"{where}: the sink ('no word applies') must have probability 0")
            worst = float(np.abs(s.sum(axis=1) - 1.0).max())
            if worst > SPEAKER_SUM_TOLERANCE:
                raise ModelContractViolation(f"{where}: each target's probabilities over messages must sum to 1 "
                                             f"(off by {worst:.3g})")
            if theory.params:
                grads = jax.grad(lambda d: jnp.sum(theory.group_speaker(d, group) ** 2))(draw)
                bad = sorted(k for k, g in grads.items() if not np.all(np.isfinite(np.asarray(g))))
                if bad:
                    raise ModelContractViolation(f"{where}: the gradient with respect to {', '.join(bad)} is not finite")


def pool_predictions(theory: TheoryModel, fitted: CorpusFit, pool: Sequence[Context],
                     max_draws: int = MAX_POOL_DRAWS) -> np.ndarray:
    """Posterior-mean listener class probabilities and speaker probabilities over the pool,
    flattened; raises ValueError when they are not finite."""
    flat = fitted.flat()
    params = {k: flat[k] for k in theory.params}
    n = len(next(iter(flat.values())))
    take = np.unique(np.linspace(0, n - 1, min(n, max_draws)).round().astype(int))
    parts = []
    for group in group_by_shape(pool).values():
        if params:
            acc_l, acc_s = 0.0, 0.0
            for k, batch in draw_batches(params, take):
                acc_l = acc_l + np.asarray(class_probs(theory.draws_probs(batch, group), group.classes)[:k],
                                           dtype=np.float64).sum(axis=0)
                acc_s = acc_s + np.asarray(theory.draws_speaker(batch, group)[:k], dtype=np.float64).sum(axis=0)
            listener, speaker = acc_l / len(take), acc_s / len(take)
        else:
            listener = np.asarray(class_probs(theory.group_probs({}, group)[None], group.classes)[0])
            speaker = np.asarray(theory.group_speaker({}, group))
        parts += [listener.reshape(-1), speaker.reshape(-1)]
    preds = np.concatenate(parts)
    if not np.all(np.isfinite(preds)):
        raise ValueError(f"{theory.name}'s predictions are not finite on some novelty-pool scenes")
    return preds


def admit(candidate_dir: Path, name: str, *, cfg: GateConfig, blocks: Sequence[Block], pool: Sequence[Context],
          admitted_preds: Mapping[str, np.ndarray]) -> Admission:
    candidate_dir = Path(candidate_dir)
    missing = read_candidate(candidate_dir)
    if missing:
        return _refuse(missing)
    path = candidate_dir / "candidate.py"
    source = path.read_text(encoding="utf-8")
    problems = code_problems(source)
    if problems:
        return _refuse("the code gate refused candidate.py: " + ", ".join(problems) +
                       ". Theory files may import jax, memo, numpyro, numpy, a few stdlib modules and "
                       "src.rsa.memo_kit only, and may not read files or reach the interpreter.")
    try:
        shape = theory_shape_problems(source)
    except SyntaxError as exc:
        return _refuse(f"candidate.py is not valid Python: {exc}")
    if shape:
        return _refuse("candidate.py is not a theory: " + "; ".join(shape))
    try:
        theory = TheoryModel(path, name=name)
        clash = sorted(set(theory.params) & link_parameter_names())
        if clash:
            return _refuse(f"its parameters {clash} belong to the links (each paradigm's response process: "
                           f"a decision temperature, a lapse, a rating's cutpoints); rename or remove them")
        scenes = unique_contexts([c for b in blocks for c in b.contexts])[0]
        for groups in (group_by_shape(scenes), group_by_shape(pool)):
            check_contract(theory, groups)
            check_speaker_contract(theory, groups)
    except ModelContractViolation as exc:
        return _refuse(f"contract: {exc}")
    except Exception as exc:  # memo compile errors, errors in the theory's own code
        if is_model_failure(exc, path):
            return _refuse(f"the theory failed to load or run: {type(exc).__name__}: {exc}")
        raise
    try:
        fitted = loop_fit(path, name, cfg.corpus_path, cfg.settings, cfg.cache_dir, time_limit_sec=cfg.time_limit_sec)
    except ModelFailure as exc:
        return _refuse(f"fitting failed: {exc}")
    if not fitted.converged:
        report = fitted.sampler_report()
        return _refuse("the fit did not converge (a near miss, R-hat ≤ 1.2, bulk ESS ≥ 20 and at most 2% divergent, "
                       "is refitted once at target_accept 0.95; a fit further off is not): "
                       + "; ".join(fitted.convergence_problems) + ". " + (report.text() + ". " if report else "")
                       + "Reparameterise (remove parameters the data cannot separate, sample on an unconstrained "
                       "scale, tighten priors) rather than relying on smaller steps.", fit=fitted)
    try:
        preds = pool_predictions(theory, fitted, pool)
    except ValueError as exc:
        return _refuse(str(exc), fit=fitted)
    nearest, dist = closest(preds, admitted_preds)
